# Verify delimiter balance after stripping comments and strings approximately; not a compiler substitute.
import re
clean=re.sub(r'/\*.*?\*/',' ',src,flags=re.S)
# Strip string literals before // comments so URI strings like kaam:// do not
# get mistaken for source comments by this lightweight delimiter check.
clean=re.sub(r'"(?:\\.|[^"\\])*"','""',clean)
clean=re.sub(r'//[^\n]*',' ',clean)
for a,b,label in [('{','}','braces'),('(',')','parentheses'),('[',']','brackets')]:
    count=0; low=0
    for c in clean:
        if c==a: count+=1
        elif c==b: count-=1; low=min(low,count)
    check(f'Kotlin {label} balanced', count==0 and low>=0, f'net={count}, minimum={low}')

